// "Which goals does this issue serve?", asked on every issue detail render.
func (q *Queries) ListGoalsForIssue(ctx context.Context, arg ListGoalsForIssueParams) ([]Goal, error) {
	rows, err := q.db.Query(ctx, listGoalsForIssue, arg.IssueID, arg.WorkspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Goal{}
	for rows.Next() {
		var i Goal
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Level,
			&i.Title,
			&i.Description,
			&i.ParentGoalID,
			&i.OrphanReason,
			&i.PrevGoalID,
			&i.ProjectID,
			&i.Kind,
			&i.Status,
			&i.OwnerType,
			&i.OwnerID,
			&i.Cycle,
			&i.DueDate,
			&i.IsRetro,
			&i.Position,
			&i.CreatedByType,
			&i.CreatedByID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const softDeleteGoal = `-- name: SoftDeleteGoal :exec
UPDATE goal SET deleted_at = now(), updated_at = now()
WHERE id = $1 AND workspace_id = $2 AND deleted_at IS NULL
`

type SoftDeleteGoalParams struct {
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

// Soft because a goal that carried milestones must stay explainable: the
// panorama needs to say why a chain is broken rather than just showing a hole.
func (q *Queries) SoftDeleteGoal(ctx context.Context, arg SoftDeleteGoalParams) error {
	_, err := q.db.Exec(ctx, softDeleteGoal, arg.ID, arg.WorkspaceID)
	return err
}

const unlinkGoalIssue = `-- name: UnlinkGoalIssue :exec
DELETE FROM goal_issue
WHERE goal_id = $1 AND issue_id = $2 AND workspace_id = $3
`

type UnlinkGoalIssueParams struct {
	GoalID      pgtype.UUID `json:"goal_id"`
	IssueID     pgtype.UUID `json:"issue_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

func (q *Queries) UnlinkGoalIssue(ctx context.Context, arg UnlinkGoalIssueParams) error {
	_, err := q.db.Exec(ctx, unlinkGoalIssue, arg.GoalID, arg.IssueID, arg.WorkspaceID)
	return err
}

const updateGoal = `-- name: UpdateGoal :one
UPDATE goal SET
    title = COALESCE($3, title),
    description = COALESCE($4, description),
    parent_goal_id = CASE WHEN $5::bool THEN NULL
                          ELSE COALESCE($6, parent_goal_id) END,
    orphan_reason = COALESCE($7, orphan_reason),
    prev_goal_id = CASE WHEN $8::bool THEN NULL
                        ELSE COALESCE($9, prev_goal_id) END,
    project_id = COALESCE($10, project_id),
    kind = COALESCE($11, kind),
    status = COALESCE($12, status),
    owner_type = COALESCE($13, owner_type),
    owner_id = COALESCE($14, owner_id),
    cycle = COALESCE($15, cycle),
    due_date = COALESCE($16, due_date),
    position = COALESCE($17, position),
    updated_at = now()
WHERE id = $1 AND workspace_id = $2 AND deleted_at IS NULL
RETURNING id, workspace_id, level, title, description, parent_goal_id, orphan_reason, prev_goal_id, project_id, kind, status, owner_type, owner_id, cycle, due_date, is_retro, position, created_by_type, created_by_id, created_at, updated_at, deleted_at
`

type UpdateGoalParams struct {
	ID           pgtype.UUID   `json:"id"`
	WorkspaceID  pgtype.UUID   `json:"workspace_id"`
	Title        pgtype.Text   `json:"title"`
	Description  pgtype.Text   `json:"description"`
	ClearParent  bool          `json:"clear_parent"`
	ParentGoalID pgtype.UUID   `json:"parent_goal_id"`
	OrphanReason pgtype.Text   `json:"orphan_reason"`
	ClearPrev    bool          `json:"clear_prev"`
	PrevGoalID   pgtype.UUID   `json:"prev_goal_id"`
	ProjectID    pgtype.UUID   `json:"project_id"`
	Kind         pgtype.Text   `json:"kind"`
	Status       pgtype.Text   `json:"status"`
	OwnerType    pgtype.Text   `json:"owner_type"`
	OwnerID      pgtype.UUID   `json:"owner_id"`
	Cycle        pgtype.Text   `json:"cycle"`
	DueDate      pgtype.Date   `json:"due_date"`
	Position     pgtype.Float8 `json:"position"`
}

// level is absent on purpose: a goal's tier is fixed at creation because its
// parent and children were chosen under that tier's rules.
func (q *Queries) UpdateGoal(ctx context.Context, arg UpdateGoalParams) (Goal, error) {
	row := q.db.QueryRow(ctx, updateGoal,
		arg.ID,
		arg.WorkspaceID,
		arg.Title,
		arg.Description,
		arg.ClearParent,
		arg.ParentGoalID,
		arg.OrphanReason,
		arg.ClearPrev,
		arg.PrevGoalID,
		arg.ProjectID,
		arg.Kind,
		arg.Status,
		arg.OwnerType,
		arg.OwnerID,
		arg.Cycle,
		arg.DueDate,
		arg.Position,
	)
	var i Goal
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Level,
		&i.Title,
		&i.Description,
		&i.ParentGoalID,
		&i.OrphanReason,
		&i.PrevGoalID,
		&i.ProjectID,
		&i.Kind,
		&i.Status,
		&i.OwnerType,
		&i.OwnerID,
		&i.Cycle,
		&i.DueDate,
		&i.IsRetro,
		&i.Position,
		&i.CreatedByType,
		&i.CreatedByID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
